import math

def build_instance(rng):
    constant = rng.randint(1, 100)
    answer = 0
    for x in range(-int(math.sqrt(constant)), int(math.sqrt(constant)) + 1):
        y_squared = constant - x ** 2
        if y_squared >= 0:
            y = int(math.sqrt(y_squared))
            if y ** 2 == y_squared:
                answer += 1
    check = 0
    for x in range(-int(math.sqrt(constant)), int(math.sqrt(constant)) + 1):
        y_squared = constant - x ** 2
        if y_squared >= 0:
            y = int(math.sqrt(y_squared))
            if y ** 2 == y_squared:
                check += 1
    parameters = {'constant': constant}
    return (parameters, answer, check)



